// adımlı planı **koşmaz**; `source="onizleme"` ile adımları geri verir. Yani bu imzadaki
// `kos?: boolean`'ın varsayılanı *«koşma, önce göster»*tir — ve bu bilinçli: bir onay
// alanının varsayılanı **her zaman** en az geri alınamaz olandır.
//
// ⚠ Tel biçimi **düz**dür (`adimlar`/`gecerli`/`note` üst düzeyde) — kapı
// `test_plan_onizleme.py` onu adıyla savunuyor. Burada tek bir `onizleme` nesnesine
// toplanır: kartı çizecek olan üç ayrı bayrağı değil **bir** nesneyi okumalı (`KAT-1`).
// ⚠ `soru` sunucudan gelmez, **çağıranın** cümlesidir: `[düzenle]` onu besteciye geri
// yazacak ve kullanıcı kendi yazdığını görmeli, makronun adını (`neden`) değil.
export async function postMakro(
  g: { ad: string; capa: CubeQuery; boyut: string; soru: string; kos?: boolean },
): Promise<AskResponse> {
  const { data } = await apiClient.post<AskResponse & {
    adimlar?: { sira: number; fiil: string; metin: string }[] | null;
    gecerli?: boolean;
  }>("/oneri/makro", g);
  const y: AskResponse = { ...data, question: data.question || g.soru };
  if (data.source !== "onizleme") return y;
  return {
    ...y,
    onizleme: {
      makro: g.ad,
      adimlar: data.adimlar ?? [],
      gecerli: data.gecerli !== false,
      note: data.note ?? "",
      soru: g.soru,
